import { dirname, join } from "node:path";
import { test } from "node:test";
import { fileURLToPath } from "node:url";

import { fixContentRefusal } from "./dependency-classify.mjs";
import { main, movePipPin, parseGroups, relockPatch, relockTarget } from "./dependency-relock.mjs";
import { unifiedDiff } from "./install-script-pin.mjs";
import { tempDir } from "../../../lib/test-tmp.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));
const COMMAND = "uv pip compile requirements.in --universal --generate-hashes --python-version 3.12 -o requirements.txt";

const SHARED_PIP_ENTRY = `version: 2
updates:
  - package-ecosystem: pip
    directories:
      - /plugins/explainer-video
      - /lib/media-render
    labels:
      - dependencies
    ignore:
      - dependency-name: "manim"
        update-types:
          - "version-update:semver-major"
    groups:
      playwright:
        group-by: dependency-name
        patterns:
          - "playwright"
      pip-minor-patch:
        patterns:
          - "*"
        update-types:
          - "minor"
  - package-ecosystem: pip
    directory: /plugins/speech
    groups:
      pip-minor-patch:
        patterns:
          - "*"
`;

const IN = (version) => `# ManimCE with Typst for math.\nmanim[typst]==0.21.0\n# Frame capture for the stills renderer.\nplaywright==${version}\n`;

