const MEDIA_RENDER_BUMPED_EXPLAINER_VIDEO_LEFT = {
  files: [
    { filename: "lib/media-render/requirements.in", status: "modified" },
    { filename: "lib/media-render/requirements.txt", status: "modified" },
  ],
  texts: {
    "lib/media-render/requirements.in": "# Frame capture.\nplaywright==1.65.2\n",
    "plugins/explainer-video/requirements.in": IN("1.65.1"),
    "plugins/explainer-video/requirements.txt": TXT("1.65.1"),
  },
};
const readFrom = (texts) => async (path) => texts[path] ?? null;

test("parseGroups reads each group-by dependency-name group with its entry's directories", () => {
  assert.deepEqual(parseGroups(SHARED_PIP_ENTRY), [{ name: "playwright", ecosystem: "pip", directories: ["plugins/explainer-video", "lib/media-render"], patterns: ["playwright"] }]);
  assert.deepEqual(parseGroups(SHARED_PIP_ENTRY.replace("group-by: dependency-name", "group-by: other")), []);
  assert.deepEqual(parseGroups(""), []);
});

test("relockTarget names the directory the group left behind, at the version the bumped one pins", async () => {
  assert.deepEqual(await relockTarget({ files: MEDIA_RENDER_BUMPED_EXPLAINER_VIDEO_LEFT.files, groups: parseGroups(SHARED_PIP_ENTRY), readText: readFrom(MEDIA_RENDER_BUMPED_EXPLAINER_VIDEO_LEFT.texts) }), {
    directory: "plugins/explainer-video",
    name: "playwright",
    from: "1.65.1",
    to: "1.65.2",
  });
});

test("relockTarget names nothing when the directories already agree or the pull request bumped both", async () => {
  const groups = parseGroups(SHARED_PIP_ENTRY);
  const agree = { ...MEDIA_RENDER_BUMPED_EXPLAINER_VIDEO_LEFT.texts, "plugins/explainer-video/requirements.in": IN("1.65.2") };
  assert.equal(await relockTarget({ files: MEDIA_RENDER_BUMPED_EXPLAINER_VIDEO_LEFT.files, groups, readText: readFrom(agree) }), null);
  const both = [...MEDIA_RENDER_BUMPED_EXPLAINER_VIDEO_LEFT.files, { filename: "plugins/explainer-video/requirements.txt", status: "modified" }];
  assert.equal(await relockTarget({ files: both, groups, readText: readFrom(MEDIA_RENDER_BUMPED_EXPLAINER_VIDEO_LEFT.texts) }), null);
  const speech = [{ filename: "plugins/speech/requirements.txt", status: "modified" }];
  assert.equal(await relockTarget({ files: speech, groups, readText: async () => assert.fail("no group directory changed") }), null);
});

test("movePipPin moves exactly one pin of the package and keeps the rest of the file", () => {
  assert.equal(movePipPin(IN("1.65.1"), { name: "Playwright", from: "1.65.1", to: "1.65.2" }), IN("1.65.2"));
  assert.throws(() => movePipPin(IN("1.65.1"), { name: "playwright", from: "1.64.0", to: "1.65.2" }), /exactly one/);
  assert.throws(() => movePipPin(IN("1.65.1"), { name: "playwright", from: "1.65.1", to: "1.65.2 --index-url x" }), /exact version/);
});

test("relockPatch writes a patch that turns the head's files into the relock, a change the fix rule admits", async () => {
  const target = { directory: "plugins/explainer-video", name: "playwright", from: "1.65.1", to: "1.65.2" };
  const runs = [];
  const run = async (files) => {
    runs.push(files);
    return TXT("1.65.2");
  };
  const { patch } = await relockPatch(target, { readText: readFrom(MEDIA_RENDER_BUMPED_EXPLAINER_VIDEO_LEFT.texts), run });
  assert.deepEqual(runs, [{ requirementsIn: IN("1.65.2"), requirementsTxt: TXT("1.65.1") }]);
  const repo = tempDir("dependency-relock-");
  execFileSync("git", ["init", "-q", repo]);
  mkdirSync(join(repo, "plugins/explainer-video"), { recursive: true });
  writeFileSync(join(repo, "plugins/explainer-video/requirements.in"), IN("1.65.1"));
  writeFileSync(join(repo, "plugins/explainer-video/requirements.txt"), TXT("1.65.1"));
  writeFileSync(join(repo, "patch.diff"), patch);
  execFileSync("git", ["-C", repo, "apply", "patch.diff"]);
  assert.equal(readFileSync(join(repo, "plugins/explainer-video/requirements.in"), "utf8"), IN("1.65.2"));
  assert.equal(readFileSync(join(repo, "plugins/explainer-video/requirements.txt"), "utf8"), TXT("1.65.2"));
  assert.equal(fixContentRefusal("plugins/explainer-video/requirements.txt", TXT("1.65.1"), TXT("1.65.2")), null);
  assert.equal(fixContentRefusal("plugins/explainer-video/requirements.in", IN("1.65.1"), IN("1.65.2")), null);
});

test("relockPatch refuses a relock that is more than pins and hashes, or that misses the pin", async () => {
  const target = { directory: "plugins/explainer-video", name: "playwright", from: "1.65.1", to: "1.65.2" };
  const readText = readFrom(MEDIA_RENDER_BUMPED_EXPLAINER_VIDEO_LEFT.texts);
  const indexed = async () => `--index-url https://evil.example/simple\n${TXT("1.65.2")}`;
  await assert.rejects(relockPatch(target, { readText, run: indexed }), /requirements-line/);
  await assert.rejects(relockPatch(target, { readText, run: async () => TXT("1.65.1") }), /does not pin playwright==1\.65\.2/);
  await assert.rejects(relockPatch(target, { readText: readFrom({}), run: indexed }), /no requirements\.in and requirements\.txt/);
});

test("unifiedDiff round-trips a change that adds and removes lines", () => {
  const dir = tempDir("dependency-relock-diff-");
  execFileSync("git", ["init", "-q", dir]);
  const before = "a\nb\nc\nd\ne\nf\ng\nh\ni\nj\nk\n";
  const after = "a\nB\nB2\nc\nd\ne\nf\ng\nh\nk\nl\n";
  writeFileSync(join(dir, "f.txt"), before);
  writeFileSync(join(dir, "p.diff"), unifiedDiff("f.txt", before, after));
  execFileSync("git", ["-C", dir, "apply", "p.diff"]);
  assert.equal(readFileSync(join(dir, "f.txt"), "utf8"), after);
});

test("check fails while a group's directories pin different versions, naming both, and passes once they agree", () => {
  const root = tempDir("dependency-relock-check-");
  mkdirSync(join(root, ".github"));
  writeFileSync(join(root, ".github/dependabot.yml"), SHARED_PIP_ENTRY);
  for (const [dir, version] of [["plugins/explainer-video", "1.65.1"], ["lib/media-render", "1.65.2"]]) {
    mkdirSync(join(root, dir), { recursive: true });
    writeFileSync(join(root, dir, "requirements.in"), IN(version));
  }
  const lines = [];
  assert.equal(main(["check", root], { log: (line) => lines.push(line) }), 1);
  assert.deepEqual(lines, ["::error file=.github/dependabot.yml::the playwright group pins playwright at different versions: plugins/explainer-video 1.65.1, lib/media-render 1.65.2; relock the directory that lags"]);
  writeFileSync(join(root, "plugins/explainer-video/requirements.in"), IN("1.65.2"));
  assert.equal(main(["check", root], { log: () => {} }), 0);
});

test("relock-requirements.sh relocks with the lock's own command and refuses a lock another command wrote", () => {
  const dir = tempDir("dependency-relock-sh-");
  const uv = join(dir, "uv");
  writeFileSync(uv, `#!/usr/bin/env bash\nprintf '%s\\n' "$@" >"${join(dir, "args")}"\n`);
  chmodSync(uv, 0o755);
  const work = join(dir, "work");
  mkdirSync(work);
  writeFileSync(join(work, "requirements.in"), IN("1.65.2"));
  writeFileSync(join(work, "requirements.txt"), TXT("1.65.1"));
  const script = join(HERE, "relock-requirements.sh");
  execFileSync("bash", [script, work], { env: { PATH: process.env.PATH, RELOCK_UV: uv } });
  const args = readFileSync(join(dir, "args"), "utf8").trim().split("\n");
  assert.deepEqual(args, ["pip", "compile", "--quiet", "--no-config", "--directory", work, ...COMMAND.split(" ").slice(3), "--custom-compile-command", COMMAND]);
  writeFileSync(join(work, "requirements.txt"), TXT("1.65.1", `${COMMAND} --index-url https://evil.example/simple`));
  assert.throws(() => execFileSync("bash", [script, work], { env: { PATH: process.env.PATH, RELOCK_UV: uv }, stdio: "pipe" }), /was not compiled by/);
});
